-- fix_all_trigger_tenant_id.sql
-- Patches all AFTER INSERT trigger functions that were omitting tenant_id
-- on child-row inserts, causing NOT NULL violations.
-- Applied as Supabase migration: fix_trigger_functions_missing_tenant_id

-- Fix trg_create_default_fund: add tenant_id
CREATE OR REPLACE FUNCTION public.trg_create_default_fund()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.funds (project_id, name, fund_type, status, is_default, created_by, tenant_id)
  VALUES (NEW.id, 'Collaboration Fund', 'collaboration', 'draft', true, NEW.owner_central_id, NEW.tenant_id);
  RETURN NEW;
END;
$function$;

-- Fix trg_bundle_creator_collab: add tenant_id
CREATE OR REPLACE FUNCTION public.trg_bundle_creator_collab()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.collaborators (object_type, object_id, user_id, role, access_source, status, tenant_id)
  VALUES ('bundle', NEW.id, NEW.creator_central_id, 'creator', 'direct', 'active', NEW.tenant_id)
  ON CONFLICT (object_type, object_id, user_id) DO NOTHING;
  RETURN NEW;
END;
$function$;

-- Fix trg_note_creator_collab: add tenant_id
CREATE OR REPLACE FUNCTION public.trg_note_creator_collab()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.collaborators (object_type, object_id, user_id, role, access_source, status, tenant_id)
  VALUES (
    CASE WHEN NEW.note_type = 'task' THEN 'task' ELSE 'note' END,
    NEW.id, NEW.owner_central_id, 'creator', 'direct', 'active', NEW.tenant_id
  )
  ON CONFLICT (object_type, object_id, user_id) DO NOTHING;
  RETURN NEW;
END;
$function$;

-- Fix ensure_note_owner_membership: add tenant_id
CREATE OR REPLACE FUNCTION public.ensure_note_owner_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  insert into public.object_memberships (object_type, object_id, user_central_id, role, tenant_id)
  values ('note', new.id, new.owner_central_id, 'owner', new.tenant_id)
  on conflict (object_type, object_id, user_central_id) do update
    set role = 'owner';
  return new;
end;
$function$;

-- Fix trg_objective_creator_collab: add tenant_id
CREATE OR REPLACE FUNCTION public.trg_objective_creator_collab()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.collaborators (object_type, object_id, user_id, role, access_source, status, tenant_id)
  VALUES ('objective', NEW.id, NEW.owner_central_id, 'creator', 'direct', 'active', NEW.tenant_id)
  ON CONFLICT (object_type, object_id, user_id) DO NOTHING;
  RETURN NEW;
END;
$function$;

-- Fix handle_new_project_owner_collaborator: add tenant_id
CREATE OR REPLACE FUNCTION public.handle_new_project_owner_collaborator()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.collaborators
    (user_id, object_id, object_type, role, access_source, invited_by, status, tenant_id)
  VALUES
    (NEW.owner_central_id, NEW.id, 'init', 'creator', 'direct', NEW.owner_central_id, 'active', NEW.tenant_id)
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$function$;

-- Fix enqueue_google_task_sync: add tenant_id to sync_outbox inserts
CREATE OR REPLACE FUNCTION public.enqueue_google_task_sync()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_owner uuid;
  v_action text;
  v_payload jsonb;
  v_dedupe text;
begin
  if (tg_op = 'INSERT') then
    if new.note_type <> 'task' then return new; end if;
    if (new.detail->>'_pull_source') = 'google' then
      new.detail = new.detail - '_pull_source';
      return new;
    end if;
    v_owner := new.owner_central_id;
    v_action := 'upsert';
    v_payload := jsonb_build_object(
      'title', coalesce(new.title, ''),
      'body', coalesce(new.body_text, ''),
      'done', coalesce(new.done, false),
      'updated_at', new.updated_at
    );
    v_dedupe := 'task:' || new.id::text;
    insert into sync_outbox (owner_central_id, provider, local_type, local_id, action, desired_container_id, payload, dedupe_key, tenant_id)
    values (v_owner, 'google_tasks', 'task', new.id, v_action, new.preferred_external_container_id, v_payload, v_dedupe, new.tenant_id);
    return new;
  elsif (tg_op = 'UPDATE') then
    if new.note_type <> 'task' then return new; end if;
    if (new.detail->>'_pull_source') = 'google' then
      new.detail = new.detail - '_pull_source';
      return new;
    end if;
    v_owner := new.owner_central_id;
    v_action := 'upsert';
    v_payload := jsonb_build_object(
      'title', coalesce(new.title, ''),
      'body', coalesce(new.body_text, ''),
      'done', coalesce(new.done, false),
      'updated_at', new.updated_at
    );
    v_dedupe := 'task:' || new.id::text;
    insert into sync_outbox (owner_central_id, provider, local_type, local_id, action, desired_container_id, payload, dedupe_key, tenant_id)
    values (v_owner, 'google_tasks', 'task', new.id, v_action, new.preferred_external_container_id, v_payload, v_dedupe, new.tenant_id);
    return new;
  elsif (tg_op = 'DELETE') then
    if old.note_type <> 'task' then return old; end if;
    v_owner := old.owner_central_id;
    v_action := 'delete';
    v_payload := jsonb_build_object('deleted_at', now());
    v_dedupe := 'task:' || old.id::text;
    insert into sync_outbox (owner_central_id, provider, local_type, local_id, action, desired_container_id, payload, dedupe_key, tenant_id)
    values (v_owner, 'google_tasks', 'task', old.id, v_action, old.preferred_external_container_id, v_payload, v_dedupe, old.tenant_id);
    return old;
  end if;
  return null;
end;
$function$;
